/**
 * Domain service that groups Contacts of the given Accounts by the
 * lower-cased domain part of their email address.
 *
 * - Respects the running user's sharing (`with sharing`).
 * - Bulk-safe: a single SOQL query for all provided Account Ids.
 * - Contacts without an email (or an email without a usable domain) are skipped.
 */
public with sharing class ContactDomainService {

    /**
     * Groups the contacts of the given accounts by the domain part of their
     * email address, lower-cased (e.g. 'Jane@Example.COM' -> 'example.com').
     *
     * @param accountIds the Account Ids whose contacts should be grouped;
     *                   null or empty yields an empty map
     * @return map of lower-cased email domain to the contacts having that domain;
     *         each contact has Id, Email and AccountId populated
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        // Null or empty input short-circuits to an empty map.
        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Single bulkified query; with sharing enforces the running user's access.
        for (Contact con : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ]) {
            String email = con.Email;
            if (String.isBlank(email)) {
                continue;
            }

            email = email.trim();
            if (email == '') {
                continue;
            }

            Integer atIndex = email.lastIndexOf('@');
            // Skip malformed addresses with no '@' or nothing after the '@'.
            if (atIndex < 0 || atIndex == email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIndex + 1).toLowerCase();
            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }
            contactsByDomain.get(domain).add(con);
        }

        return contactsByDomain;
    }
}
