@isTest
private class ShippingCostCalculatorTest {

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static void assertQuote(
        Decimal expected,
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue,
        String message
    ) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        System.assertEquals(expected, actual, message);
    }

    private static void assertShippingException(
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue,
        String message
    ) {
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
            System.assert(false, 'Expected ShippingException but none was thrown: ' + message);
        } catch (ShippingCostCalculator.ShippingException e) {
            // expected
        } catch (Exception e) {
            System.assert(
                false,
                'Expected ShippingCostCalculator.ShippingException but got ' +
                    e.getTypeName() + ': ' + message
            );
        }
    }

    // ------------------------------------------------------------------
    // Base price by weight, including all boundaries
    // ------------------------------------------------------------------

    @isTest
    static void testBasePriceByWeight() {
        // lowest valid weight still falls into the first tier
