```apex
/**
 * Handles incoming FB_Shipment_Event__e platform events and marks the
 * matching FB_Sales_Order__c records as shipped.
 *
 * Guarantees:
 * - Exactly one SOQL query and one DML statement per invocation.
 * - Unknown order numbers are ignored.
 * - Cancelled orders are never modified.
 * - When several events in one call refer to the same order, the last
 *   event in the list wins.
 */
public inherited sharing class ShipmentEventHandler {

    /**
     * Processes a batch of shipment events.
     *
     * @param events the platform events received by the trigger
     */
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Last one wins: iterating in list order and overwriting map entries
        // ensures only the final event per order number survives.
        Map<String, FB_Shipment_Event__e> lastEventByOrderNumber = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }
            // Order_Number__c is stored upper case on the order; normalise
            // the incoming value so the lookup always matches.
            String orderNumber = event.Order_Number__c.trim().toUpperCase();
            lastEventByOrderNumber.put(orderNumber, event);
        }

        if (lastEventByOrderNumber.isEmpty()) {
            return;
        }

        // Single SOQL query for all referenced orders.
        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :lastEventByOrderNumber.keySet()
        ];

        // Index the orders by their (upper case) order number.
        Map<String, FB_Sales_Order__c> ordersByNumber = new Map<String, FB_Sales_Order__c>();
        for (FB_Sales_Order__c order : orders) {
            ordersByNumber.put(order.Order_Number__c.trim().toUpperCase(), order);
        }

        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        for (String orderNumber : lastEventByOrderNumber.keySet()) {
            FB_Sales_Order__c order = ordersByNumber.get(orderNumber);

            // Unknown order number: ignore.
            if (order == null) {
                continue;
            }

            // Cancelled orders are never changed.
            if (order.Status__c == 'Cancelled') {
                continue;
            }

            FB_Shipment_Event__e winningEvent = lastEventByOrderNumber.get(orderNumber);

            order.Status__c          = 'Shipped';
            order.Tracking_Number__c = winningEvent.Tracking_Number__c;
            order.Carrier__c         = winningEvent.Carrier__c;
            order.Shipped_Date__c    = Date.today();

            ordersToUpdate.add(order);
        }

        // Single DML statement for all updates.
        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
}
