public with sharing class OpportunityPipelineHandler {

    /**
     * Keeps Account.FB_Open_Pipeline__c (sum of Amount of open Opportunities)
     * and Account.FB_Open_Opportunities__c (count of open Opportunities) correct.
     *
     * Design notes:
     *  - Totals are always recomputed from the database on every trigger invocation.
     *    No static "already processed" caching, so several DML statements on the same
     *    records within one transaction (e.g. a Flow followed by Apex, or a test
     *    method with multiple DMLs) always see up-to-date totals.
     *  - The only recursion guard needed against the legacy AccountTrigger (which
     *    updates open Opportunities on every Account update) is a value comparison:
     *    accounts whose stored totals already equal the freshly computed totals are
     *    not re-written, which stops the Account -> Opportunity -> Account chain.
     *  - All SOQL and DML are bulk-safe (set-based, no queries/updates inside loops).
     *  - Blank Amounts contribute 0 (SUM ignores NULL), and an account with no open
     *    Opportunities shows 0 / 0, never blank.
     */

    public static void handleAfterInsert(List<Opportunity> newOpps) {
        recalculate(accountIdsFrom(newOpps));
    }

    public static void handleAfterUpdate(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        // An update can affect both the old and the new account
        // (amount/stage change affects the current account; a re-parent affects both).
        Set<Id> accountIds = accountIdsFrom(newOpps);
        accountIds.addAll(accountIdsFrom(oldOpps));
        recalculate(accountIds);
    }

    public static void handleAfterDelete(List<Opportunity> oldOpps) {
        recalculate(accountIdsFrom(oldOpps));
    }

    public static void handleAfterUndelete(List<Opportunity> newOpps) {
        recalculate(accountIdsFrom(newOpps));
    }

    private static Set<Id> accountIdsFrom(List<Opportunity> opps) {
        Set<Id> accountIds = new Set<Id>();
        if (opps == null) {
            return accountIds;
        }
        for (Opportunity opp : opps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        // Current stored totals. This reads through any earlier DML in the same
        // transaction, so repeated statements on the same records stay correct.
        Map<Id, Account> accounts = new Map<Id, Account>([
            SELECT Id,
                   FB_Open_Pipeline__c,
                   FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        // Fresh aggregate of open opportunities per account.
        Map<Id, Decimal> sumsById = new Map<Id, Decimal>();
        Map<Id, Integer> countsById = new Map<Id, Integer>();
        for (AggregateResult row : [
            SELECT AccountId accId,
                   SUM(Amount) amountSum,
                   COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) row.get('accId');
            Decimal amountSum = (Decimal) row.get('amountSum');
            sumsById.put(accId, amountSum == null ? 0 : amountSum);
            countsById.put(accId, (Integer) row.get('oppCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Account acc = accounts.get(accId);
            if (acc == null) {
                continue; // Account no longer exists; nothing to update.
            }

            Decimal newPipeline = sumsById.containsKey(accId) ? sumsById.get(accId) : 0;
            Integer newCount = countsById.containsKey(accId) ? countsById.get(accId) : 0;

            Boolean changed = false;

            if (acc.FB_Open_Pipeline__c == null
                    || acc.FB_Open_Pipeline__c != newPipeline) {
                acc.FB_Open_Pipeline__c = newPipeline;
                changed = true;
            }

            if (acc.FB_Open_Opportunities__c == null
                    || acc.FB_Open_Opportunities__c != newCount) {
                acc.FB_Open_Opportunities__c = newCount;
                changed = true;
            }

            if (changed) {
                accountsToUpdate.add(acc);
            }
        }

        // Only writing accounts whose totals actually changed is what prevents the
        // legacy AccountTrigger (after update -> updates open Opportunities) from
        // looping: on the follow-up Opportunity update the totals already match and
        // no further Account DML is issued.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
