/**
 * @description Service that computes closed-won Opportunity revenue per Account
 *              for the current calendar year. Sums are calculated entirely in
 *              the database via a single aggregate SOQL query, so no individual
 *              Opportunity records are loaded into heap.
 *              The class is `inherited sharing`, so the aggregate query runs
 *              with the row-level sharing of the calling context, respecting
 *              the running user's access.
 */
public inherited sharing class OpportunityRollupService {

    /**
     * @description Returns the sum of `Amount` over won opportunities
     *              (`IsWon = true`) with a `CloseDate` in the current calendar
     *              year, grouped per Account.
     * @param accountIds The set of Account Ids to compute rollups for. A null
     *                   or empty set yields an empty map.
     * @return A map keyed by exactly the requested Account Ids. Accounts with
     *         no qualifying opportunities, or whose qualifying opportunities
     *         all have a blank `Amount`, map to 0 (never null). Ids that were
     *         not requested never appear as keys.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        // Null or empty input => empty map.
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Seed every requested account with 0 so accounts without qualifying
        // opportunities (or with only blank Amounts) still appear, mapped to 0.
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        // Single aggregate query: SUM ignores null Amounts, so opportunities
        // with a blank Amount contribute nothing. Accounts with no qualifying
        // rows are simply absent from the grouped results and keep their
        // seeded value of 0.
        // Note: `WITH USER_MODE` is not supported on aggregate queries; the
        // `inherited sharing` class modifier ensures the query respects the
        // running user's row-level sharing in the calling context.
        for (AggregateResult aggregate : [
            SELECT AccountId accountId,
                   SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) aggregate.get('accountId');
            Decimal totalAmount = (Decimal) aggregate.get('totalAmount');

            // SUM over rows where Amount is null on every row returns null;
            // normalize to 0 as required.
            result.put(accountId, totalAmount == null ? 0 : totalAmount);
        }

        return result;
    }
