public inherited sharing class Opportunities extends fflib_SObjectDomain {
    private static final String CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities(sObjects);
        }
    }

    public void onAfterInsert() {
        startFulfilmentForNewlyWon();
    }

    public void onAfterUpdate(Map<Id, SObject> existingRecords) {
        startFulfilmentForNewlyWon((Map<Id, SObject>) existingRecords);
    }

    private void startFulfilmentForNewlyWon() {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.StageName == CLOSED_WON) {
                opportunityIds.add(opp.Id);
            }
        }
        startFulfilment(opportunityIds);
    }

    private void startFulfilmentForNewlyWon(Map<Id, SObject> existingRecords) {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.StageName == CLOSED_WON
                && existingRecords.containsKey(opp.Id)
                && ((Opportunity) existingRecords.get(opp.Id)).StageName != CLOSED_WON) {
                opportunityIds.add(opp.Id);
            }
        }
        startFulfilment(opportunityIds);
    }

    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }
        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
        service.startFulfilment(opportunityIds);
    }
}
