/**
 * Domain class for Opportunity, following the Apex Enterprise Patterns
 * (fflib-apex-common). All Opportunity trigger logic is routed here by
 * OpportunityTrigger via fflib_SObjectDomain.triggerHandler.
 */
public with sharing class Opportunities extends fflib_SObjectDomain
{
    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    /**
     * Standard constructable inner class, allowing the fflib library to
     * build this domain for any set of Opportunity SObjects.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    /**
     * Bulk-safe before insert logic: apply defaults only for fields the
     * caller has not supplied. Runs only on insert (never on update),
     * and mutates the records in place so no extra DML is required.
     */
    public override void onBeforeInsert()
    {
        for (Opportunity record : (List<Opportunity>) Records)
        {
            if (record.get('CloseDate') == null)
            {
                record.put(
                    'CloseDate',
                    Date.today().addDays(30)
                );
            }

            if (record.get('Type') == null)
            {
                record.put('Type', 'New Customer');
            }
        }
    }
}
