     * @return The Contact SObject type.
     */
    global override Schema.SObjectType getSObjectType()
    {
        return Contact.SObjectType;
    }

    /**
     * @description The fields queried by this selector.
     * @return The list of Contact fields selected by this selector.
     */
    global override List<Schema.SObjectField> getSObjectFieldList()
    {
        return new List<Schema.SObjectField>
        {
            Contact.Id,
            Contact.FirstName,
            Contact.LastName,
            Contact.Email,
            Contact.Title,
            Contact.AccountId
        };
    }

    /**
     * @description Selects the contacts with the given ids, with all selector
     *              fields populated, in a single query. An empty (or null) set
     *              of ids returns an empty list without executing a query.
     * @param contactIds The set of Contact ids to select.
     * @return The matching Contact records.
     */
    global List<Contact> selectById(Set<Id> contactIds)
    {
        // Guard clause: avoid a query with an empty bind collection
        if (contactIds == null || contactIds.isEmpty())
        {
            return new List<Contact>();
        }

        // Bulk-safe and SOQL-injection safe: the where clause only binds the
        // in-memory set variable; no string concatenation of user input.
        return (List<Contact>) Database.query(getQuery('Id IN :contactIds'));
    }
}
