public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';

    /**
     * No-argument constructor used by the Application selector factory
     * (fflib_Application.SelectorFactory calls new AccountsSelector()).
     *
     * Sets the selector's data access setting to user mode so that every
     * query built by this selector runs as WITH USER_MODE. The platform
     * then enforces the running user's object and field CRUD/FLS and
     * sharing rules at query time: a user who cannot read one of the
     * selected fields gets an exception instead of the data.
     */
    public AccountsSelector() {
        setAccessLevel(System.AccessLevel.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * Base fields plus whatever fields the admins have placed on the
     * Credit_Review field set (currently AnnualRevenue and Rating). The
     * field set is read dynamically, so admins can add or remove fields
     * without any code change here.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fieldList = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        for (Schema.FieldSetMember member : SObjectType.Account.fieldSets.getMap()
                .get(CREDIT_REVIEW_FIELD_SET)
                .getFields()) {
            fieldList.add(member.getSObjectField());
        }

        return fieldList;
    }

    /**
     * Standard by-id query; uses fflib's selectSObjectsById, which builds
     * the query via newQueryFactory() and therefore inherits this selector's
     * user-mode data access setting along with the full field list above.
     */
    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns the accounts together with their Contacts children in a single
     * query.
     *
     * The account query is built through this selector's query factory, so it
     * selects this selector's fields (including the Credit_Review field set)
     * and carries its user-mode access level, producing WITH USER_MODE. The
     * contact subquery is built from the existing ContactsSelector so it uses
     * that selector's field list. WITH USER_MODE on the statement applies to
     * the child subquery as well, so contact fields are FLS-checked too, and
     * the FROM Contacts relationship already restricts the rows to the
     * accounts being queried.
     *
     * fflib_QueryFactory does not support subqueries, so the subquery is
     * injected into the generated SOQL immediately before the parent's
     * FROM clause.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        // Contact fields taken from the existing ContactsSelector
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : new ContactsSelector().getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }
        String contactsSubQuery =
            '(SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)';

        fflib_QueryFactory accountQueryFactory = newQueryFactory(false, false)
            .setCondition('Id IN :accountIds');

        String soql = accountQueryFactory.toSOQL();

        Integer fromIndex = soql.indexOf('FROM ');
        if (fromIndex < 0) {
            throw new IllegalStateException('Unexpected SOQL generated by fflib_QueryFactory: ' + soql);
        }

        soql = soql.substring(0, fromIndex).trim()
            + ', ' + contactsSubQuery + ' '
            + soql.substring(fromIndex);

        return (List<Account>) Database.query(soql);
    }
}
