public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    private static final String CLOSED_STATUS = 'Closed';

    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate first: nothing is read or written when the reason is blank.
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        // Nothing to do when no cases were supplied.
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        List<Case> casesToEscalate = new List<Case>();
        List<Task> tasksToCreate = new List<Task>();

        Date activityDate = Date.today().addDays(1);

        for (Case c : cases) {
            if (c.Status == CLOSED_STATUS || c.IsEscalated) {
                continue;
            }

            Case escalatedCase = new Case(
                Id = c.Id,
                IsEscalated = true,
                Priority = 'High'
            );
            casesToEscalate.add(escalatedCase);

            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = activityDate,
                Priority = 'High'
            );
            tasksToCreate.add(escalationTask);
        }

        // Only open a unit of work (and commit) when there is actually work to do.
        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_Application.IUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Case c : casesToEscalate) {
            uow.registerDirty(c);
        }
        for (Task t : tasksToCreate) {
            uow.registerNew(t);
        }

        uow.commitWork();
    }
}
