public with sharing class LeadContactMatcher {

    /**
     * For each lead, returns the Id of the first contact (in the given order)
     * whose email matches the lead's email. Matching ignores case and
     * leading/trailing whitespace. Blank emails never match.
     * Does not query or modify any records.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        // Build a normalized-email -> contact Id index once (O(m)).
        // "First contact in list order wins" is preserved because an
        // existing entry is never overwritten by later duplicates.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        for (Contact contact : contacts) {
            String normalizedEmail = normalizeEmail(contact.Email);
            if (String.isNotBlank(normalizedEmail)
                    && !contactIdByEmail.containsKey(normalizedEmail)) {
                contactIdByEmail.put(normalizedEmail, contact.Id);
            }
        }

        // Resolve each lead via a single map lookup (O(n) overall).
        List<Id> results = new List<Id>();
        for (Lead lead : leads) {
            String normalizedEmail = normalizeEmail(lead.Email);
            Id matchedContactId = null;
            if (String.isNotBlank(normalizedEmail)) {
                matchedContactId = contactIdByEmail.get(normalizedEmail);
            }
            results.add(matchedContactId);
        }

        return results;
    }

    /**
     * Normalizes an email for comparison: trims leading/trailing whitespace
     * and lowercases it. Returns null for null input; blank handling is done
     * by the caller via isNotBlank on the normalized value.
     */
    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
