 *
 * NOTE ON THE sendEmail INVOCATION LIMIT:
 * Messaging.sendEmail may be invoked at most 10 times per Apex transaction.
 * sendReminders() below follows the "one sendEmail call per opportunity"
 * approach and therefore only works reliably for runs of up to 10
 * opportunities. For the 200-opportunity runs described for the scheduled
 * job, use sendRemindersChunked(), which sends messages in batches with
 * allOrNone=false so a single bad recipient never blocks the others while
 * staying well inside the invocation limit.
 */
public inherited sharing class RenewalReminderService {

    /** Maximum opportunities the scheduled job passes in a single run. */
    public static final Integer MAX_OPPORTUNITIES_PER_RUN = 200;

    /**
     * Emails the owner of each given opportunity that a renewal is due.
     *
     * One Messaging.sendEmail call per opportunity, so a failure on one
     * email does not prevent the others from being sent.
     *
     * IMPORTANT: because sendEmail may only be invoked 10 times per
     * transaction, this method throws an uncatchable LimitException if
     * called with more than 10 opportunity Ids. Prefer sendRemindersChunked
     * for production volumes.
     *
     * @param opportunityIds Ids of the opportunities whose owners to remind.
     * @return the number of emails that were sent successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Map<Id, Opportunity> opportunitiesById = queryOpportunities(opportunityIds);

        Integer sentCount = 0;
        for (Id opportunityId : opportunityIds) {
            Opportunity opp = opportunitiesById.get(opportunityId);
            if (opp == null) {
                // Id did not match an accessible opportunity; skip it.
                continue;
            }

            try {
                Messaging.SingleEmailMessage mail = buildReminderEmail(opp);
                List<Messaging.SendEmailResult> results =
                    Messaging.sendEmail(
                        new List<Messaging.Email>{ mail },
                        false // allOrNone=false: this call only affects this one email
                    );
                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                } else {
                    logSendErrors(opp.Id, opp.OwnerId, results);
                }
            } catch (Exception e) {
                // A bad owner Id (e.g. a queue), inactive user, or
                // deliverability problem on this email must not abort
                // the remaining reminders.
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService: failed to send reminder for ' +
                    'Opportunity ' + opp.Id + ' to owner ' + opp.OwnerId + ': ' +
                    e.getMessage()
                );
            }
        }
        return sentCount;
    }

    /**
     * Same behaviour and return value as sendReminders, but safe for the
     * scheduled job's volumes: builds one email per opportunity and sends
     * them in chunks of up to 100 messages per sendEmail call with
     * allOrNone=false. A failure on any individual message only fails that
     * message; the rest still go out, and only successful messages are
     * counted.
     */
    public static Integer sendRemindersChunked(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Map<Id, Opportunity> opportunitiesById = queryOpportunities(opportunityIds);

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        List<Opportunity> queuedOpportunities = new List<Opportunity>();
        for (Id opportunityId : opportunityIds) {
            Opportunity opp = opportunitiesById.get(opportunityId);
            if (opp != null) {
                messages.add(buildReminderEmail(opp));
                queuedOpportunities.add(opp);
            }
        }

        Integer sentCount = 0;
        final Integer chunkSize = 100; // per-call message limit for sendEmail
        Integer index = 0;
        while (index < messages.size()) {
            // Build the chunk manually; Apex List has no subList().
            List<Messaging.SingleEmailMessage> chunk = new List<Messaging.SingleEmailMessage>();
            List<Opportunity> chunkOpps = new List<Opportunity>();
            while (index < messages.size() && chunk.size() < chunkSize) {
                chunk.add(messages[index]);
                chunkOpps.add(queuedOpportunities[index]);
                index++;
            }

            List<Messaging.SendEmailResult> results =
                Messaging.sendEmail(chunk, false); // allOrNone=false
            if (results != null) {
                for (Integer j = 0; j < results.size(); j++) {
                    Messaging.SendEmailResult result = results[j];
                    if (result != null && result.isSuccess()) {
                        sentCount++;
                    } else {
                        Opportunity failedOpp = chunkOpps[j];
                        logSendErrors(failedOpp.Id, failedOpp.OwnerId, results);
                    }
                }
            }
        }
        return sentCount;
    }

    /**
     * Bulk-safe lookup of the data needed to build the emails.
     * A single query, no SOQL inside loops.
     */
    private static Map<Id, Opportunity> queryOpportunities(List<Id> opportunityIds) {
        return new Map<Id, Opportunity>(
            [
                SELECT Id, Name, CloseDate, OwnerId
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );
    }

    /**
     * Builds the reminder email for one opportunity.
     * Targeting the owner by User Id with SaveAsActivity=false means the
     * email does not consume the org's daily allocation for external emails.
     */
    private static Messaging.SingleEmailMessage buildReminderEmail(Opportunity opp) {
        Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
        mail.setTargetObjectId(opp.OwnerId);
        mail.setSaveAsActivity(false);
        mail.setSubject('Renewal due: ' + opp.Name);

        String closeDateLabel = (opp.CloseDate == null)
            ? 'not set'
            : opp.CloseDate.format();
        mail.setPlainTextBody(
            'Hello,\n\n' +
            'The renewal for the opportunity "' + opp.Name + '" is due.\n' +
            'Close date: ' + closeDateLabel + '\n\n' +
            'Please review the opportunity and follow up with the customer.\n\n' +
            'Thank you.'
        );
        return mail;
    }

    /**
     * Logs per-message errors returned by sendEmail.
     */
    private static void logSendErrors(
        Id opportunityId,
        Id ownerId,
        List<Messaging.SendEmailResult> results
    ) {
        if (results == null || results.isEmpty()) {
            System.debug(
                LoggingLevel.ERROR,
                'RenewalReminderService: no send result for Opportunity ' +
                opportunityId + ' to owner ' + ownerId
            );
            return;
        }
        for (Messaging.SendEmailResult result : results) {
            if (result != null && !result.isSuccess()) {
                List<String> errors = new List<String>();
                if (result.getErrors() != null) {
                    for (Messaging.SendEmailError err : result.getErrors()) {
                        errors.add(err.getMessage());
                    }
                }
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService: send failed for Opportunity ' + opportunityId +
                    ' to owner ' + ownerId + ': ' + String.join(errors, '; ')
                );
            }
        }
    }
}
