import { api, wire, LightningElement } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    // Provided by the record page; '$recordId' in the wire config makes the
    // wire reactive, so a changed recordId (e.g. a reused console tab)
    // automatically re-fetches the new record.
    @api recordId;

    record;
    error;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    get name() {
        return this.record?.fields?.Name?.value;
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get annualRevenue() {
        return this.record?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        // Relationship field shape: fields.Owner.value.fields.Name.value
        return this.record?.fields?.Owner?.value?.fields?.Name?.value;
    }

    get hasRecord() {
        return !!this.record;
    }

    get hasError() {
        return !!this.error;
    }

    get isLoading() {
        return !this.hasRecord && !this.hasError;
    }
}
