import { LightningElement, api } from 'lwc';
import Favorite_Add from '@salesforce/label/c.Favorite_Add';
import Favorite_Remove from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    labels = {
        add: Favorite_Add,
        remove: Favorite_Remove,
    };

    // Private reactive state. Kept separate from the public property so the
    // component can render an optimistic flip on click without ever writing
    // back to the @api property (which the parent owns).
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        // Coerce defensively; the parent may pass undefined/null.
        this._favorite = !!value;
    }

    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    get buttonLabel() {
        // The tooltip describes the action a click will perform.
        return this._favorite ? Favorite_Remove : Favorite_Add;
    }

    get iconName() {
        return this._favorite ? 'utility:favorite' : 'utility:favorite';
    }

    get iconVariant() {
        return this._favorite ? 'warning' : 'inverse';
    }

    handleClick() {
        // Optimistic UI: flip the displayed state immediately...
        this._favorite = !this._favorite;

        // ...then notify the parent so it can persist the change.
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: {
                    favorite: this._favorite,
                },
            })
        );
    }
}
