import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE
} from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    recordId;

    // Hold the Lightning message context for subscribing and publishing.
    @wire(MessageContext)
    messageContext;

    // A single active subscription, held only while the component is in the DOM.
    _subscription = null;

    subscribeToMessageChannel() {
        // Never hold more than one subscription at a time.
        if (this._subscription) {
            return;
        }
        this._subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeToMessageChannel() {
        if (this._subscription) {
            unsubscribe(this._subscription);
            this._subscription = null;
        }
    }

    // Subscribe when inserted; also handles re-insertion (e.g. a reopened tab).
    connectedCallback() {
        this.subscribeToMessageChannel();
    }

    // Release the subscription when removed from the page.
    disconnectedCallback() {
        this.unsubscribeToMessageChannel();
    }

    handleMessage(message) {
        // Show the account whose Id came in the message, or clear the panel
        // when the message has no recordId.
        this.recordId = message && message.recordId ? message.recordId : null;
    }

    // Broadcast a clear so every listening component resets its selection.
    handleClear() {
        publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
    }
}
