import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    state = 'loading';
    opportunities = [];
    errorMessage;

    connectedCallback() {
        // Imperative call exactly once when the component is inserted into the page.
        this.loadOpportunities();
    }

    get isLoading() {
        return this.state === 'loading';
    }

    get hasData() {
        return this.state === 'data';
    }

    get hasError() {
        return this.state === 'error';
    }

    get hasOpportunities() {
        return this.opportunities.length > 0;
    }

    get isEmpty() {
        return this.opportunities.length === 0;
    }

    loadOpportunities() {
        this.state = 'loading';
        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result || [];
                this.errorMessage = undefined;
                this.state = 'data';
            })
            .catch((error) => {
                this.errorMessage = error && error.body ? error.body.message : 'Unknown error';
                this.state = 'error';
            });
    }

    handleRetry() {
        this.loadOpportunities();
    }
}
