/**
 * @description GiftImportService
 *
 * Entry point for one-off website gifts. Instead of letting the integration insert
 * Contacts and Opportunities directly (which kept creating duplicate donors), this
 * service stages every gift as an NPSP Data Import (npsp__DataImport__c) record and
 * hands the staged rows to NPSP's own data import engine (BDI) through its Apex API
 * (BDI_API.run). NPSP therefore applies the org's Data Import settings
 * (npsp__Data_Import_Settings__c): contact matching on first name + last name + email,
 * automatic household creation, and donation processing that never matches existing
 * donations.
 *
 * The staged npsp__DataImport__c records are intentionally left in the org after
 * processing: NPSP writes the outcome back onto them (npsp__Status__c,
 * npsp__Contact1Imported__c, npsp__DonationImported__c, npsp__FailureInformation__c),
 * so they remain in the org as the audit trail of what was imported.
 *
 * BDI_API.run processes the staged rows synchronously, in the same transaction, so
 * the results can be read back from the Data Import records and returned to the
 * caller immediately.
 *
 * Bulk safety: all gifts received in one call (e.g. 200) are staged with a single
 * partial-success DML and processed with a single BDI run. A row NPSP rejects is
 * reported on its own ImportResult and never stops the other rows.
 */
public with sharing class GiftImportService {

    // NPSP expects the donor role on the donation to be the Contact1 side of the gift.
    private static final String DONOR_CONTACT1 = 'Contact1';

    // NPSP marks a successfully imported row with this status.
    private static final String STATUS_IMPORTED = 'Imported';

    /** One gift received from the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** Outcome for a single gift, returned in the same order as the input list. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * @description Stages one NPSP Data Import record per gift, processes them
     *              synchronously with NPSP's data import Apex API (using the org's
     *              Data Import settings), and returns one ImportResult per gift in
     *              input order.
     * @param gifts the website gifts to import; may be null or empty
     * @return one ImportResult per gift, in the same order as the input; an empty
     *         list for a null or empty input
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Pre-create a result slot per gift so results are always returned in input
        // order, including entries that never make it into a Data Import record.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;
            result.contactId = null;
            result.opportunityId = null;
            result.errorMessage = null;
            results.add(result);
        }

        // ---- Stage: one npsp__DataImport__c per gift (kept as the audit trail) ----
        // Populating only the staging fields lets NPSP apply its own contact matching
        // (first name + last name + email, per the org's Data Import settings) and
        // donation processing (no matching of existing donations).
        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            if (gift == null) {
                // A null entry cannot be staged; fail only that result and continue.
                results[i].errorMessage = 'Gift entry was null; nothing to import.';
                continue;
            }

            stagedImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = DONOR_CONTACT1
            ));
            stagedIndexes.add(i);
        }

        if (!stagedImports.isEmpty()) {
            // Partial-success insert: a row rejected by a validation rule must not
            // stop the other gifts from being staged and imported. Successfully
            // staged rows stay in the org as the audit trail.
            List<Database.SaveResult> stagingResults = Database.insert(stagedImports, false);

            Map<Id, Integer> giftIndexByDataImportId = new Map<Id, Integer>();
            List<npsp__DataImport__c> insertedImports = new List<npsp__DataImport__c>();

            for (Integer j = 0; j < stagedImports.size(); j++) {
                Integer giftIndex = stagedIndexes[j];
                if (stagingResults[j].isSuccess()) {
                    giftIndexByDataImportId.put(stagedImports[j].Id, giftIndex);
                    insertedImports.add(stagedImports[j]);
                } else {
                    results[giftIndex].errorMessage =
                        buildStagingErrorMessage(stagingResults[j].getErrors());
                }
            }

            if (!giftIndexByDataImportId.isEmpty()) {
                runDataImportEngine(giftIndexByDataImportId, insertedImports, results);
            }
        }

        return results;
    }

    /**
     * @description Hands the staged rows to NPSP's data import engine synchronously
     *              (same transaction) and builds the ImportResults from the outcome
     *              NPSP wrote back onto each Data Import record. A row NPSP rejects
     *              is marked Failed with details in npsp__FailureInformation__c and
     *              never halts the other rows.
     */
    private static void runDataImportEngine(
        Map<Id, Integer> giftIndexByDataImportId,
        List<npsp__DataImport__c> stagedImports,
        List<ImportResult> results
    ) {
        String runExceptionMessage = null;

        // NPSP's Apex API for data import. This invokes the BDI engine synchronously,
        // in the current transaction, applying the org's npsp__Data_Import_Settings__c
        // (contact matching on first name/last name/email; no donation matching).
        try {
            BDI_API.run(stagedImports);
        } catch (Exception e) {
            // A whole-run failure must not roll everything back; rows without an NPSP
            // outcome are failed individually below with this message.
            runExceptionMessage = 'NPSP Data Import API failed: ' + e.getMessage();
        }

        // Read NPSP's per-row results back from the processed Data Import records.
        Map<Id, npsp__DataImport__c> processedImports = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__FailureInformation__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c
            FROM npsp__DataImport__c
            WHERE Id IN :giftIndexByDataImportId.keySet()
        ]);

        for (Id dataImportId : giftIndexByDataImportId.keySet()) {
            ImportResult result = results[giftIndexByDataImportId.get(dataImportId)];
            npsp__DataImport__c dataImport = processedImports.get(dataImportId);

            if (dataImport == null) {
                // Defensive: the row could not be read back after processing.
                result.success = false;
                result.errorMessage = (runExceptionMessage != null)
                    ? runExceptionMessage
                    : 'Staged Data Import record could not be read after processing.';
                continue;
            }

            Boolean imported = (dataImport.npsp__Status__c == STATUS_IMPORTED)
                || dataImport.npsp__DonationImported__c != null;

            if (imported) {
                // NPSP imported the row: the donation was processed and the contact
                // was matched (existing donor) or created (new donor).
                result.success = true;
                result.contactId = dataImport.npsp__Contact1Imported__c;
                result.opportunityId = dataImport.npsp__DonationImported__c;
            } else {
                // NPSP rejected this row; carry its failure information so the caller
                // knows why, without affecting the other rows.
                result.success = false;
                String failureInfo = dataImport.npsp__FailureInformation__c;
                if (String.isBlank(failureInfo)) {
                    failureInfo = (runExceptionMessage != null)
                        ? runExceptionMessage
                        : 'NPSP could not import this row (status: '
                            + dataImport.npsp__Status__c + ').';
                }
                result.errorMessage = failureInfo;
            }
        }
    }

    /** Flattens the DML errors from staging into a single message for one result. */
    private static String buildStagingErrorMessage(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        if (errors != null) {
            for (Database.Error err : errors) {
                messages.add(err.getMessage());
            }
        }
        return 'Failed to stage the NPSP Data Import record: '
            + String.join(messages, '; ');
    }
}
