/**
 * GiftService
 * Records a gift (Closed Won Opportunity) that has already been received, wired up
 * the way NPSP expects when the org uses the Household Account model and NPSP Payments:
 *
 *   - The Opportunity is attributed to the Contact's Household Account.
 *   - The donor Contact is the NPSP Primary Contact and holds the "Donor" Opportunity
 *     Contact Role; every other member of the household holds the "Household Member"
 *     Opportunity Contact Role (exactly one role per Contact).
 *   - Exactly one NPSP Payment exists: paid, for the full amount, dated the gift date.
 *
 * NPSP triggers (TDTM) may automatically create a Payment and/or Contact Roles when the
 * Opportunity is inserted, so after the insert we reconcile what exists before adding
 * anything, which guarantees there are never duplicates.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a gift received from the given Contact on the given date.
     *
     * @param contactId the Id of the donor Contact (must exist and belong to a Household Account)
     * @param amount    the gift amount; must be a positive number
     * @param giftDate  the date the gift was received/closed; defaults to today if not supplied
     * @return          the Id of the created Opportunity
     * @throws IllegalArgumentException if the Contact does not exist, or amount is null/zero/negative
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInput(contactId, amount);

        Date closeDate = (giftDate != null) ? giftDate : Date.today();

        Contact donor = getDonor(contactId);

        Opportunity opp = new Opportunity(
            Name = buildOpportunityName(donor, closeDate),
            AccountId = donor.AccountId,
            StageName = STAGE_CLOSED_WON,
            CloseDate = closeDate,
            Amount = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert opp;

        ensureSingleContactRoles(opp.Id, donor.AccountId, donor.Id);
        ensureSinglePayment(opp.Id, amount, closeDate);

        return opp.Id;
    }

    /**
     * Validates the caller-supplied arguments.
     */
    private static void validateInput(Id contactId, Decimal amount) {
        if (contactId == null) {
            throw new IllegalArgumentException('A Contact Id must be provided.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-zero number.');
        }
    }

    /**
     * Loads the donor Contact. In the Household Account model, the Contact's Account
     * is the Household Account, so AccountId must be populated.
     */
    private static Contact getDonor(Id contactId) {
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = donors[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact does not belong to a Household Account: ' + contactId
            );
        }
        return donor;
    }

    /**
     * Builds the Opportunity name: "<FirstName> <LastName> Donation <yyyy-MM-dd>".
     * Date.toString() renders in yyyy-MM-dd format.
     */
    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String firstNamePart = (donor.FirstName == null) ? '' : donor.FirstName + ' ';
        return firstNamePart + donor.LastName + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Guarantees exactly one Opportunity Contact Role per household member:
     * the donor gets "Donor", everyone else in the household gets "Household Member".
     * Any roles that already exist for the Opportunity (e.g. created by automation)
     * are removed first so no Contact can end up with more than one role.
     */
    private static void ensureSingleContactRoles(Id oppId, Id householdAccountId, Id donorContactId) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
        ];
        if (!existingRoles.isEmpty()) {
            delete existingRoles;
        }

        List<Contact> members = [
            SELECT Id, FirstName, LastName
            FROM Contact
            WHERE AccountId = :householdAccountId
        ];

        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();
        for (Contact member : members) {
            roles.add(new OpportunityContactRole(
                OpportunityId = oppId,
                ContactId = member.Id,
                Role = (member.Id == donorContactId) ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER
            ));
        }
        if (!roles.isEmpty()) {
            insert roles;
        }
    }

    /**
     * Guarantees exactly one NPSP Payment for the Opportunity: paid, for the full
     * amount, with both the payment date and scheduled date set to the gift date.
     * NPSP may auto-create one or more scheduled Payments when the Opportunity is
     * inserted; in that case we reconcile the first Payment to the gift details and
     * remove any extras, so a duplicate Payment is never created.
     */
    private static void ensureSinglePayment(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c,
                   npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
        ];

        if (payments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            insert payment;
        } else {
            npe01__OppPayment__c payment = payments[0];
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            update payment;

            if (payments.size() > 1) {
                List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < payments.size(); i++) {
                    extras.add(payments[i]);
                }
                delete extras;
            }
        }
    }
}
