```apex
/**
 * @description Determines which records the running user is allowed to edit,
 * as reported by the UserRecordAccess object. UserRecordAccess is the only
 * mechanism that accounts for the full access calculation in one place:
 * object CRUD/FLS, record ownership, role hierarchy, sharing rules, manual
 * shares, Apex managed sharing, implicit parent access, and the
 * View All Data / Modify All Data / View All / Modify All permissions.
 *
 * A single SOQL query against UserRecordAccess can filter RecordId with an
 * IN-bind over an arbitrary collection of IDs spanning multiple objects,
 * so up to 2,000 IDs (the documented per-call contract here) are resolved
 * with exactly one query. To stay bulk-safe if a caller ever exceeds the
 * documented maximum, IDs are processed in chunks of 2,000 per query,
 * which keeps the 20-query budget intact for the supported input size.
 *
 * Implementation note: bind variables are not supported in the LIMIT clause
 * of a UserRecordAccess query (the platform fails to compile such a query),
 * so the chunk size is expressed as a literal. The RecordId IN-bind still
 * guarantees the query can never match more records than the chunk size.
 */
public with sharing class RecordAccessService {

    /**
     * @description Maximum number of record IDs evaluated per SOQL query.
     * Matches the documented per-call maximum so the normal case is one query.
     */
    private static final Integer CHUNK_SIZE = 2000;

    /**
     * @description Returns the subset of the given record IDs that the running
     * user can edit (UserRecordAccess.HasEditAccess = true).
     *
     * @param recordIds IDs possibly spanning multiple objects; may be null or empty.
     * @return The editable subset, deduplicated. Never null; an empty set when
     *         the input is null, empty, or contains no non-null IDs.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        // Contract: null or empty input yields an empty set, never null.
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        // Normalize: drop nulls and duplicates so the bind variable is clean
        // and the query is not asked to match a null RecordId.
        Set<Id> candidates = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                candidates.add(recordId);
            }
        }
        if (candidates.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editable = new Set<Id>();

        // Resolve access in chunks. One query covers the documented
        // 2,000-ID maximum; chunking merely protects callers that send more.
        for (List<Id> chunk : chunkIds(candidates)) {
            for (UserRecordAccess access : [
                    SELECT RecordId
                    FROM UserRecordAccess
                    WHERE UserId = :UserInfo.getUserId()
                      AND HasEditAccess = true
                      AND RecordId IN :chunk
                    LIMIT 2000
            ]) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }

    /**
     * @description Splits the candidate IDs into chunks of at most CHUNK_SIZE
     * so each SOQL query stays within a predictable, boundable size.
     *
     * @param ids The deduplicated, non-null candidate IDs.
     * @return A list of ID chunks, each with at most CHUNK_SIZE elements.
     */
    private static List<List<Id>> chunkIds(Set<Id> ids) {
        List<List<Id>> chunks = new List<List<Id>>();
        List<Id> current = new List<Id>();
        for (Id id : ids) {
            current.add(id);
            if (current.size() == CHUNK_SIZE) {
                chunks.add(current);
                current = new List<Id>();
            }
        }
        if (!current.isEmpty()) {
            chunks.add(current);
        }
        return chunks;
    }
}
