/**
 * @description Service for importing contacts migrated from a legacy system.
 *
 * Migrated contacts are existing customers, so the "Send welcome pack" task
 * action (TA_Contact_CreateWelcomeTask) must NOT run for them. All other
 * Contact automation (e.g. TA_Contact_FormatPhone on before insert) must
 * still execute normally.
 *
 * The bypass is scoped to the single TAF action (not the whole Contact
 * object) using MetadataTriggerHandler.bypass(actionName), and it is always
 * released in a finally block so that any contacts inserted later in the
 * same transaction are processed by the full automation suite again.
 *
 * Bulk-safe: all contacts are inserted in a single DML statement and the
 * trigger actions run once over the whole list.
 */
public inherited sharing class ContactImportService {

    /**
     * @description Name of the Trigger Actions Framework action that must be
     *              skipped for imported contacts. In TAF 0.3.4 actions are
     *              registered by the name of the class that implements the
     *              TriggerAction.* interface, which is the name used by
     *              MetadataTriggerHandler.bypass / clearBypass / isBypassed.
     */
    private static final String WELCOME_TASK_ACTION_NAME = 'TA_Contact_CreateWelcomeTask';

    /**
     * @description Inserts the given contacts in one DML statement with the
     *              TA_Contact_CreateWelcomeTask trigger action skipped while
     *              all other Contact automation runs. The bypass is removed
     *              before the method returns, even if the insert throws.
     *
     * @param contacts The contacts to import. A null or empty list is a
     *                 no-op, avoiding an unnecessary bypass and an empty
     *                 DML statement.
     */
    public static void importContacts(List<Contact> contacts) {
        // Nothing to do - avoid taking a bypass and an empty DML statement.
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass only the welcome-task action, not the whole Contact object,
        // so TA_Contact_FormatPhone and any other registered Contact actions
        // still run for the imported rows.
        MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION_NAME);

        try {
            // Single DML statement; the TAF trigger handler consults the
            // bypass when the after-insert actions are resolved, so the
            // welcome task action is skipped for this insert only.
            insert contacts;
        } finally {
            // Always release the bypass so contacts inserted later in the
            // same transaction receive their welcome task as usual. Running
            // in a finally block guarantees this even if the DML fails.
            MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION_NAME);
        }
    }
}
