File: force-app/main/default/classes/TA_Opportunity_CollectForErpSync.cls
/**
 * Trigger Actions Framework action for Opportunity (after insert / after update).
 *
 * Responsibility: collect the Ids of the opportunities of the CURRENT DML
 * operation that must be pushed to the ERP.
 *   - after insert: every opportunity of the operation.
 *   - after update: only the opportunities whose StageName changed.
 *
 * The Ids are buffered in OpportunityErpSyncFinalizer, which the framework
 * invokes once at the end of each DML operation. Because the trigger handler
 * runs once per trigger chunk (e.g. a 250-row insert runs in chunks of
 * 200 + 50), this action must never enqueue anything itself; it only
 * accumulates Ids. The finalizer then enqueues exactly one
 * OpportunityErpSyncJob per DML operation with all of that operation's Ids,
 * and no job at all when none are pending.
 *
 * This class is bulk-safe and performs no SOQL and no DML.
 */
public with sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static final Schema.sObjectField STAGE_NAME_FIELD = Opportunity.StageName;

    /**
     * After insert, every opportunity of the DML operation must be pushed to
     * the ERP.
     */
    public void afterInsert(List<sObject> triggerNew) {
        OpportunityErpSyncFinalizer.collect(triggerNew);
    }

    /**
     * After update, only opportunities whose StageName changed must be pushed
     * to the ERP. Comparisons are done per chunk against the old records of
     * the same chunk, so the check is bulk-safe and recursion-safe.
     */
    public void afterUpdate(List<sObject> triggerNew, List<sObject> triggerOld) {
        Map<Id, sObject> oldRecordsById = new Map<Id, sObject>(triggerOld);
        List<sObject> stageChangedRecords = new List<sObject>();
        for (sObject record : triggerNew) {
            sObject oldRecord = oldRecordsById.get(record.Id);
            if (oldRecord == null) {
                // Cannot happen in a well-formed after update context; ignore defensively.
                continue;
            }
            String newStageName = (String) record.get(STAGE_NAME_FIELD);
            String oldStageName = (String) oldRecord.get(STAGE_NAME_FIELD);
            if (newStageName != oldStageName) {
                stageChangedRecords.add(record);
            }
        }
        OpportunityErpSyncFinalizer.collect(stageChangedRecords);
    }
}
