 * Trigger Actions Framework DML finalizer for the Opportunity to ERP sync.
 *
 * The framework calls every registered DML finalizer (DML_Finalizer__mdt
 * record "OpportunityErpSyncFinalizer") at the end of EVERY DML operation it
 * handles, whatever the sObject. Therefore this class must be side-effect
 * free unless there is actually something to sync: it enqueues a job only
 * when the buffer is non-empty, and it drains the buffer first, so that
 * exactly one OpportunityErpSyncJob is enqueued per DML operation, carrying
 * every Id collected by TA_Opportunity_CollectForErpSync for that operation
 * (including all trigger chunks of the same operation, e.g. 200 + 50).
 *
 * Two separate DML statements in the same transaction therefore yield two
 * jobs, each holding only its own operation's records, because the buffer is
 * drained at the end of each DML operation.
 *
 * Finalizers must not perform DML. System.enqueueJob is asynchronous
 * registration (not DML) and participates in the current transaction, so the
 * enqueued job is discarded if the transaction later rolls back.
 */
public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    /**
     * Ids collected by the trigger actions for the DML operation currently in
     * flight. Cleared as soon as the job for that operation is enqueued.
     */
    @testVisible
    private static Set<Id> pendingOpportunityIds = new Set<Id>();

    /**
     * Called by TA_Opportunity_CollectForErpSync (once per trigger chunk) to
     * buffer the opportunities of the current DML operation that need to be
     * synced. A Set is used so duplicate Ids within one operation collapse.
     */
    public static void collect(List<sObject> records) {
        if (records == null) {
            return;
        }
        for (sObject record : records) {
            if (record != null && record.get('Id') != null) {
                pendingOpportunityIds.add((Id) record.get('Id'));
            }
        }
    }

    /**
     * Called by the framework at the end of every DML operation it handles,
     * whatever the sObject. Enqueues exactly one OpportunityErpSyncJob when,
     * and only when, the just-completed DML operation touched opportunities
     * that need to be pushed to the ERP.
     */
    public void execute(FinalizerHandler.Context context) {
        if (pendingOpportunityIds.isEmpty()) {
            // DML on another object, or nothing to sync for this operation.
            return;
        }
        // Drain the buffer BEFORE enqueueing so this finalizer stays correct
        // even if it is invoked again (e.g. for a subsequent DML operation in
        // the same transaction).
        Set<Id> opportunityIds = pendingOpportunityIds;
        pendingOpportunityIds = new Set<Id>();
        System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
    }
}
