```apex
/**
 * @description Trigger Action for the Trigger Actions Framework (Case).
 *
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's Cases
 * with IsClosed = false. Cases without an Account are ignored. An account whose
 * last open case goes away is explicitly set to 0 (never blank).
 *
 * Recalculation is always done from a fresh aggregate query, so the action is
 * idempotent and self-correcting for every operation that fires it: insert
 * (open or closed), close, reopen, move to another account, delete, undelete.
 *
 * Limits per trigger execution: at most two SOQL queries (one aggregate on Case,
 * one on Account) and one DML statement (update of only the affected Accounts,
 * and only those whose stored value actually changes).
 */
public inherited sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    private static final String ACCOUNT_ID_FIELD = 'AccountId';
    private static final String OPEN_CASE_COUNT_FIELD = 'FB_Open_Case_Count__c';

    /**
     * @description After insert: recalculate the accounts of the new cases. Cases
     * created already closed contribute nothing, but the parent account still gets
     * its correct value (0 instead of blank if it has no open cases).
     */
    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    /**
     * @description After update: recalculate only when IsClosed or AccountId changed
     * (close, reopen, move). When a case moves, both the old and the new account are
     * recalculated so neither is left stale.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Case> newCases = (List<Case>) triggerNew;
        List<Case> oldCases = (List<Case>) triggerOld;
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < newCases.size(); i++) {
            Case newCase = newCases[i];
            Case oldCase = oldCases[i];
            if (newCase.IsClosed != oldCase.IsClosed || newCase.AccountId != oldCase.AccountId) {
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    /**
     * @description After delete: the deleted rows no longer appear in the aggregate
     * query, so the remaining counts, including 0, are written back.
     */
    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds(triggerOld));
    }

    /**
     * @description After undelete: the restored cases are visible to the aggregate
     * query, so the affected accounts get their counts back.
     */
    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    /**
     * @description Collects the non-null AccountId values from the trigger records.
     * @param records the trigger records; null AccountIds (cases without an account) are skipped
     * @return set of distinct Account ids touched by this trigger execution
     */
    private static Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Id accountId = (Id) record.get(ACCOUNT_ID_FIELD);
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
        return accountIds;
    }

    /**
     * @description Recomputes the open case count for the given accounts and writes
     * back only the accounts whose stored value differs.
     * @param accountIds accounts touched by the trigger
     */
    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1 of 2: current number of open cases per affected account.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult row : [
                SELECT AccountId, COUNT(Id) caseCount
                FROM Case
                WHERE AccountId IN :accountIds
                      AND IsClosed = false
                GROUP BY AccountId
        ]) {
            Id accountId = (Id) row.get(ACCOUNT_ID_FIELD);
            Integer caseCount = ((Decimal) row.get('caseCount')).intValue();
            openCountByAccountId.put(accountId, caseCount);
        }

        // Query 2 of 2: read the stored value so we only update accounts that
        // really change, and convert blank to 0 where required.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds
        ]) {
            Integer targetCount = openCountByAccountId.containsKey(account.Id)
                    ? openCountByAccountId.get(account.Id)
                    : 0;
            Decimal storedCount = account.FB_Open_Case_Count__c;
            if (storedCount == null || storedCount.intValue() != targetCount) {
                Account changedAccount = new Account(Id = account.Id);
                changedAccount.put(OPEN_CASE_COUNT_FIELD, targetCount);
                accountsToUpdate.add(changedAccount);
            }
        }

        // DML 1 of 1. Account has no trigger in this org, so updating Account
        // does not re-enter the Case trigger and no recursion guard is needed.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
