```apex
/**
 * @description After-update Trigger Action for Opportunity (Trigger Actions Framework).
 * Creates one completed Task with Subject "Amount changed" on each Opportunity whose
 * Amount changed on update. Inserts are out of scope.
 *
 * Recursion safety: other actions on this trigger (for example TA_Opportunity_RoundAmount,
 * which re-updates the same opportunities in the same transaction) cause this action to run
 * again for the same records. The rounding is a consequence of the user's change, not a
 * separate change, so this action guarantees at most one "Amount changed" Task per
 * Opportunity per transaction. Static state is per transaction, so genuine changes in later
 * transactions are still audited.
 *
 * Bulk safety: collects all audit Tasks in memory and performs a single insert DML per
 * trigger execution; handles 200 opportunities per update.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    private static final String AUDIT_SUBJECT = 'Amount changed';
    private static final String AUDIT_STATUS = 'Completed';

    // Opportunity Ids already evaluated in the current transaction. The first execution of
    // this action for a record decides whether the user's update changed the Amount; every
    // later execution for the same record in the same transaction is skipped, so recursive
    // re-updates by other actions never produce an additional Task.
    private static Set<Id> processedRecordIds = new Set<Id>();

    /**
     * @description Creates the audit Tasks for opportunities whose Amount changed.
     * @param triggerNew The updated Opportunity records.
     * @param triggerOld The Opportunity records before the update.
     */
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> auditTasks = new List<Task>();

        for (Opportunity newOpp : triggerNew) {
            if (processedRecordIds.contains(newOpp.Id)) {
                continue;
            }
            Opportunity oldOpp = oldById.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }
            // Mark the record as processed for this transaction regardless of whether its
            // Amount changed, so the rounding re-update cannot create a second Task (nor a
            // false positive on records the user did not change).
            processedRecordIds.add(newOpp.Id);

            // Null-safe comparison: fires only when the Amount actually changed.
            if (newOpp.Amount != oldOpp.Amount) {
                auditTasks.add(new Task(
                    Subject = AUDIT_SUBJECT,
                    Status = AUDIT_STATUS,
                    WhatId = newOpp.Id
                ));
            }
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }
}
